package com.familyguard.child;
import android.app.Activity; import android.os.Bundle; import android.Manifest; import android.content.pm.PackageManager; import android.os.Build; import android.widget.*;
public class MainActivity extends Activity { private TextView state; public void onCreate(Bundle b){ super.onCreate(b); LinearLayout root=new LinearLayout(this); root.setOrientation(1); root.setPadding(32,48,32,32); root.setBackgroundColor(0xFFF5F7FB); TextView title=new TextView(this); title.setText("FamilyGuard Child"); title.setTextSize(28); title.setTextColor(0xFF18243A); TextView info=new TextView(this); info.setText("This device is ready for transparent family pairing."); Button location=new Button(this); location.setText("Enable Location Permission"); state=new TextView(this); state.setText("Location sharing is off."); location.setOnClickListener(v->{ if(Build.VERSION.SDK_INT>=23 && checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED) requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},42); else state.setText("Permission granted. Live sharing needs backend setup."); }); root.addView(title); root.addView(info); root.addView(location); root.addView(state); setContentView(root); } public void onRequestPermissionsResult(int r,String[] p,int[] g){ super.onRequestPermissionsResult(r,p,g); if(r==42 && g.length>0 && g[0]==PackageManager.PERMISSION_GRANTED) state.setText("Permission granted. Live sharing needs backend setup."); else if(r==42) state.setText("Location permission not granted."); } }
